handleRecordAmountInput(value) {
  const raw = String(value == null ? '' : value).replace(/,/g, '')
  if (raw === '') {
    this.form.recordAmountNew = ''
    return
  }
  const match = raw.match(/^(\d*)(\.\d{0,2})?$/)
  if (!match) {
    // 非法输入（含非数字字符）：丢弃本次改动
    this.form.recordAmountNew = this.form.recordAmountNew
    return
  }
  const intPart = match[1] || ''
  const decPart = match[2] || ''
  if (intPart.length > 10) {
    this.form.recordAmountNew = intPart.slice(0, 10) + decPart
  } else {
    this.form.recordAmountNew = intPart + decPart
  }
},

