/**
 * 备案总价归一化：整数部分最多 10 位、小数最多 2 位。
 * 保留用户当前输入形态（含末尾小数点），仅做长度与位数截断。
 * 兼容千分位逗号。
 */
normalizeRecordAmount(value) {
  const raw = String(value == null ? '' : value).replace(/,/g, '').replace(/[^\d.]/g, '')
  if (raw === '') return ''
  const firstDot = raw.indexOf('.')
  let intPart = firstDot === -1 ? raw : raw.slice(0, firstDot)
  let decPart = firstDot === -1 ? '' : raw.slice(firstDot + 1).replace(/\./g, '')
  intPart = intPart.slice(0, 10)
  decPart = decPart.slice(0, 2)
  return firstDot === -1 ? intPart : `${intPart}.${decPart}`
},
/** 备案总价输入：整数部分最多 10 位、小数最多 2 位，输入过程中即强制约束 */
