  // 仅改 model 不会同步回显），并尽量保持光标位置。
  if (nativeInput && nativeInput.value !== normalized) {
    const prevCaret = typeof nativeInput.selectionStart === 'number' ? nativeInput.selectionStart : normalized.length
    const cleanedLen = String(nativeInput.value).replace(/,/g, '').length
